node.doctext:
Hi<P>

I'm trying to create an iterator which takes a list of subs and creates the cross product of the returned lists:<P>

the expected result is
<c>
for my $x ( $sub_x->() ) {
    for my $y ( $sub_y->() ) {
         return [ $x,$y ];
    }
}
</c><P>

Please note that an iterator can be interrupted and resumed, and that the numbers of subs (=nesting levels) should be free.<P>

Since function calls are expensive in Perl I tried to implement it as a big while loop instead of recursive calls.<P>

Now I'm wondering if there is a more elegant or faster way to code this:<P>

<c>
use 5.12.0;

use strict;
use warnings;
use Data::Dump qw/pp dd/;


my $DBG;

;;; # skipped

$DBG = 0;
my $i_cross = cross(
                    sub {"A".."B"},
                    sub {1..2},
                    sub {"a".."b"},
                   );


my $count = 4;

while ( my ($v) = $i_cross->() ) {
    warn  "*** First 5 RESULTs: ", pp $v;
    last unless $count--;
}

warn "stopped";

while ( my ($v) = $i_cross->() ) {
    warn  "*** Remaining RESULT: ", pp $v;
}


sub cross {
    my @stack  = @_;
    my $level  = 0;
    my @ranges = ();
    my @res;

    return sub {

        while ( $level >= 0 ) {

            my $ra_range = \ $ranges[$level];

            # ENTER LOOP
            unless (defined $$ra_range ) {
                $$ra_range = [ $stack[$level]->() ];
                warn "ENTER level=$level left \@ranges=" ,pp \@ranges  if $DBG;
            }

            # LOOP OVER
            if ( @$$ra_range  ) {
                $res[$level] = shift @$$ra_range ;

                # deepest level?
                if ( $level == $#stack ) {
                    return [@res];
                }
                # go deeper
                else {
                    $level++;
                }

            }

            #EXIT LOOP:
            else {
                $level--;
                $$ra_range = undef;
            }

        }
        return;
    }
}

</c><P>

